  "body": "Your profile needs some improvements before we can approve it. Please check the feedback below, make the necessary updates, and resubmit when ready. We're here to help you create the perfect profile!"
}

{
  "subject": "🌟 Welcome to QR Dating - Custom Design!",
  "body": "Your registration has been approved with our premium styling!",
  "htmlTemplate": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{{subject}}</title>
    <style>
        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            margin: 0;
            padding: 0;
            background: linear-gradient(45deg, #ff6b6b, #4ecdc4, #45b7d1, #96ceb4);
            background-size: 400% 400%;
            animation: gradientShift 15s ease infinite;
        }
        @keyframes gradientShift {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
        }
        .container {
            max-width: 650px;
            margin: 40px auto;
            background: rgba(255, 255, 255, 0.95);
            backdrop-filter: blur(20px);
            border-radius: 25px;
            box-shadow: 0 25px 70px rgba(0, 0, 0, 0.3);
            overflow: hidden;
            border: 1px solid rgba(255, 255, 255, 0.3);
        }
        .header {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            text-align: center;
            padding: 40px 20px;
            position: relative;
        }
        .header::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 100" fill="rgba(255,255,255,0.1)"><path d="M0,50 Q250,0 500,50 T1000,50 L1000,100 L0,100 Z"/></svg>') no-repeat center bottom;
            background-size: cover;
        }
        .header h1 {
            font-size: 2.5em;
            margin: 0;
            text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
            position: relative;
            z-index: 1;
        }
        .content {
            padding: 40px;
            font-size: 16px;
            line-height: 1.8;
            color: #333;
        }
        .welcome-box {
            background: linear-gradient(135deg, #ff6b6b, #ee5a6f);
            color: white;
            padding: 30px;
            border-radius: 20px;
            margin: 30px 0;
            text-align: center;
            box-shadow: 0 15px 35px rgba(238, 90, 111, 0.4);
            transform: translateY(-5px);
        }
        .welcome-box h2 {
            font-size: 1.8em;
            margin: 0 0 15px 0;
            text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.3);
        }
        .feature-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 20px;
            margin: 30px 0;
        }
        .feature-card {
            background: linear-gradient(135deg, #667eea, #764ba2);
            color: white;
            padding: 25px;
            border-radius: 15px;
            text-align: center;
            box-shadow: 0 10px 25px rgba(102, 126, 234, 0.3);
        }
        .feature-card h3 {
            margin: 0 0 10px 0;
            font-size: 1.3em;
        }
        .cta-button {
            display: inline-block;
            background: linear-gradient(135deg, #4ecdc4, #44a08d);
            color: white;
            padding: 18px 40px;
            text-decoration: none;
            border-radius: 50px;
            font-weight: bold;
            font-size: 1.1em;
            margin: 25px 0;
            box-shadow: 0 15px 35px rgba(78, 205, 196, 0.4);
            transition: all 0.3s ease;
            text-align: center;
            display: block;
            width: fit-content;
            margin-left: auto;
            margin-right: auto;
        }
        .cta-button:hover {
            transform: translateY(-3px);
            box-shadow: 0 20px 40px rgba(78, 205, 196, 0.6);
        }
        .footer {
            background: #f8f9fa;
            text-align: center;
            padding: 25px;
            color: #666;
            font-size: 14px;
            border-top: 1px solid #e9ecef;
        }
        .social-links {
            margin: 15px 0;
        }
        .social-links a {
            display: inline-block;
            width: 40px;
            height: 40px;
            background: linear-gradient(135deg, #667eea, #764ba2);
            color: white;
            text-decoration: none;
            border-radius: 50%;
            line-height: 40px;
            margin: 0 10px;
            transition: transform 0.3s ease;
        }
        .social-links a:hover {
            transform: scale(1.1);
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>💕 QR Dating App</h1>
        </div>
        <div class="content">
            <div class="welcome-box">
                <h2>🎉 Welcome {{userName}}!</h2>
                <p>{{body}}</p>
            </div>

            <p>You're now part of our exclusive community where meaningful connections happen through innovative QR technology!</p>

            <div class="feature-grid">
                <div class="feature-card">
                    <h3>🎯 Smart Matching</h3>
                    <p>AI-powered compatibility</p>
                </div>
                <div class="feature-card">
                    <h3>📱 QR Cards</h3>
                    <p>50 premium cards delivered</p>
                </div>
                <div class="feature-card">
                    <h3>🔒 Privacy First</h3>
                    <p>Your data stays secure</p>
                </div>
            </div>

            <a href="{{dashboardUrl}}" class="cta-button">Start Your Journey →</a>
        </div>
        <div class="footer">
            <div class="social-links">
                <a href="#">📘</a>
                <a href="#">📷</a>
                <a href="#">🐦</a>
            </div>
            <p>© {{currentYear}} QR Dating App. All rights reserved.</p>
            <p>Questions? Reply to this email or visit our support center.</p>
        </div>
    </div>
</body>
</html>"
}

